import {scheduleChanges} from './solver.mjs';
export const activityAccesses=(r,id)=>r.access.filter(x=>x.activity_id===id).sort((a,b)=>a.week-b.week);
export function activityAdvice(r,id){const a=r.modelInfo.activities.find(a=>a.id===id),rows=activityAccesses(r,id),pred=a.predecessor?activityAccesses(r,a.predecessor):[],effective=Math.max(a.start,pred.length?Math.max(...pred.map(x=>x.week))+1:1),standardFinish=effective+Math.ceil(a.workload)-1,available=Math.max(0,a.due-effective+1),minimumECLO=Math.max(0,Math.ceil(2*(a.workload-available))),finish=rows.length?Math.max(...rows.map(x=>x.week)):null;return{a,effective,standardFinish,available,minimumECLO,ecloCanFit:available>0&&minimumECLO<=available,earlierStart:a.due-Math.ceil(a.workload)+1,finish,late:finish!==null&&finish>a.due,predFinish:pred.length?Math.max(...pred.map(x=>x.week)):null};}
export function comparePlans(base,current){const changed=scheduleChanges(base,current);return{changed,unchanged:current.modelInfo.activities.length-changed.length,metrics:['objective_score','overrun_days_total','eclo_nights_total','excess_access_nights_total'].map(key=>({key,before:base.report[key],after:current.report[key],delta:current.report[key]-base.report[key]})),rows:changed.map(id=>{const before=activityAccesses(base,id),after=activityAccesses(current,id),a=current.modelInfo.activities.find(a=>a.id===id);return{id,contract:a.contract,before:before.map(x=>'W'+x.week+(x.eclo?'*':'')).join(', '),after:after.map(x=>'W'+x.week+(x.eclo?'*':'')).join(', '),beforeFinish:Math.max(0,...before.map(x=>x.week)),afterFinish:Math.max(0,...after.map(x=>x.week))};})};}
export function changeEvidence(base,current,id){const exp=current.experiment||{},rows=activityAccesses(base,id),a=current.modelInfo.activities.find(a=>a.id===id),hits=(exp.disruptions||[]).filter(d=>a.core.includes(d.location)&&rows.some(x=>x.week>=d.from&&x.week<=d.to));const reasons=[];if(exp.startWeeks?.[id])reasons.push('Start-week input changed to W'+exp.startWeeks[id]+'.');for(const h of hits)reasons.push('Baseline occupied '+h.location+' during the reduced-capacity interval W'+h.from+'–'+h.to+'.');if(a.predecessor&&scheduleChanges(base,current).includes(a.predecessor))reasons.push('Predecessor '+a.predecessor+' also changed; finish-to-start precedence still applies.');const dd=current.decisions[id]||[];for(const x of dd.slice(0,5))reasons.push('W'+x.week+': '+x.reason+(x.blockers?.length?' (activities considered in conflicting slots: '+x.blockers.join(', ')+')':'')+'.');return reasons.length?reasons:['The selected re-optimised plan uses a different placement. No direct input change or specific deferral was recorded for this activity; this is not proof of a unique cause.'];}
